contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public function: tests interaction of Initialized with SetMinSum/SetLogFile
    // params: _min (value for SetMinSum), _log (address for SetLogFile)
    function run(uint _min, address _log) public payable {
        // read initial intitalized flag via public variable (note: in original contract it's named intitalized and has no getter, but we observe behavior via calls)
        // We'll first attempt SetMinSum and SetLogFile before calling Initialized to observe they do NOT revert, then call Initialized, then observe that subsequent SetMinSum/SetLogFile revert.

        bool before_setmin_reverted;
        bool before_setlog_reverted;
        bool after_setmin_reverted;
        bool after_setlog_reverted;

        // First attempt: should not revert (contract starts with intitalized == false)
        c.SetMinSum(_min); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            before_setmin_reverted = true;
        } else {
            before_setmin_reverted = false;
        }

        c.SetLogFile(_log); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            before_setlog_reverted = true;
        } else {
            before_setlog_reverted = false;
        }

        // Now call Initialized()
        c.Initialized(); if (__ESBMC_reverted()) return;

        // After initialization, SetMinSum and SetLogFile should revert (they check intitalized and revert if true)
        c.SetMinSum(_min); bool __rev2 = __ESBMC_reverted(); if (__rev2) {
            after_setmin_reverted = true;
        } else {
            after_setmin_reverted = false;
        }

        c.SetLogFile(_log); bool __rev3 = __ESBMC_reverted(); if (__rev3) {
            after_setlog_reverted = true;
        } else {
            after_setlog_reverted = false;
        }

        // Assert general rule:
        // - Before calling Initialized, SetMinSum and SetLogFile must NOT both have reverted (at least one should be allowed to succeed when intitalized is false);
        // - After calling Initialized, both SetMinSum and SetLogFile must revert.
        // This uses only observable behavior (whether calls reverted) and parameters.
        assert((!(before_setmin_reverted && before_setlog_reverted)) && (after_setmin_reverted && after_setlog_reverted));
    }

    receive() external payable {}
}

