// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 _min, address _log) internal {
        bool before_setmin_reverted;
        bool before_setlog_reverted;
        bool after_setmin_reverted;
        bool after_setlog_reverted;
        try c.SetMinSum(_min) {
            before_setmin_reverted = false;
        } catch {
            before_setmin_reverted = true;
        }
        try c.SetLogFile(_log) {
            before_setlog_reverted = false;
        } catch {
            before_setlog_reverted = true;
        }
        try c.Initialized() {} catch { return; }
        try c.SetMinSum(_min) {
            after_setmin_reverted = false;
        } catch {
            after_setmin_reverted = true;
        }
        try c.SetLogFile(_log) {
            after_setlog_reverted = false;
        } catch {
            after_setlog_reverted = true;
        }
        assertTrue((!(before_setmin_reverted && before_setlog_reverted)) && (after_setmin_reverted && after_setlog_reverted));
    }

    function testFuzz_run(uint256 _min, address _log) public {
        vm.assume(_log.code.length == 0 && uint160(_log) > 0xffff && _log != address(this) && _log != address(c) && _log != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && _log != 0x000000000000000000636F6e736F6c652e6c6f67 && _log != 0x4e59b44847b379578588920cA78FbF26c0B4956C && _log != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(_min, _log);
    }

    receive() external payable {}
}
